CREATE OR REPLACE FUNCTION public.mha_admin_assign_existing_user(p_user_email text, p_username text, p_company_id bigint, p_role_id bigint, p_store_ids bigint[], p_default_store_id bigint, p_is_active boolean DEFAULT true)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\ndeclare v_user uuid;v_count integer;\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n select id into v_user from auth.users where lower(email)=lower(trim(p_user_email));\n if v_user is null then raise exception 'User must first be created in Supabase Authentication by an authorized administrator';end if;\n if exists(select 1 from public.mha_super_admin_identity where user_id=v_user) then raise exception 'Pinned Super Admin cannot be reassigned';end if;\n if length(trim(coalesce(p_username,''))) not between 2 and 120 then raise exception 'Invalid username';end if;\n if not exists(select 1 from public.mha_company where id=p_company_id and is_active) then raise exception 'Active company required';end if;\n if not exists(select 1 from public.mha_role where id=p_role_id and company_id=p_company_id and is_active) then raise exception 'Active company role required';end if;\n if p_store_ids is null or cardinality(p_store_ids)=0 or p_default_store_id is null or not p_default_store_id=any(p_store_ids) then raise exception 'Default store must be assigned';end if;\n select count(distinct s.id) into v_count from public.mha_store s where s.id=any(p_store_ids) and s.company_id=p_company_id and s.is_active;\n if v_count<>cardinality(p_store_ids) then raise exception 'All assigned stores must be unique, active and within one company';end if;\n insert into public.mha_user_profile(user_id,username,company_id,role_id,default_store_id,is_active,is_super_admin)\n values(v_user,trim(p_username),p_company_id,p_role_id,p_default_store_id,coalesce(p_is_active,true),false)\n on conflict(user_id) do update set username=excluded.username,company_id=excluded.company_id,role_id=excluded.role_id,default_store_id=excluded.default_store_id,is_active=excluded.is_active,is_super_admin=false;\n delete from public.mha_user_store where user_id=v_user;\n insert into public.mha_user_store(user_id,company_id,store_id)\n select v_user,p_company_id,unnest(p_store_ids);\n return v_user;\nend $function$\n